    age: 68,
    sex: "M",
    bed: "A-102",
    strokeType: "Ischemic (MCA)",
    affectedSide: "right",
    acuteDay: 6,
    severity: "moderate",
    notes: "Right hemiparesis, good motivation. Family present most afternoons.",
    profile: SEVERITY_PROFILES.moderate,
