const SESSION_HOURS = [9, 11.5, 14, 16.5, 19];

function isoDate(d: Date): string {
  return d.toISOString().slice(0, 10);
}

function daysAgo(n: number): Date {
  const d = new Date();
  d.setDate(d.getDate() - n);
  return d;
}

export function seedIfEmpty(db: Db): void {
  const existing = db.select({ id: schema.patients.id }).from(schema.patients).limit(1).all();
  if (existing.length > 0) return;
  seed(db);
}

export function seed(db: Db): void {
  db.delete(schema.samples).run();
  db.delete(schema.reps).run();
  db.delete(schema.safetyEvents).run();
  db.delete(schema.sessions).run();
  db.delete(schema.protocols).run();
  db.delete(schema.patients).run();

  const now = new Date();

  for (const p of PATIENTS) {
    const admission = daysAgo(p.acuteDay - 1);
    db.insert(schema.patients)
      .values({
        id: p.id,
        name: p.name,
        age: p.age,
        sex: p.sex,
        bed: p.bed,
        strokeType: p.strokeType,
        affectedSide: p.affectedSide,
        admissionDate: isoDate(admission),
        severity: p.severity,
        notes: p.notes,
        baselineCapacity: p.profile.baselineCapacity,
        recoveryRate: p.profile.recoveryRate,
        fatigueRate: p.profile.fatigueRate,
        spasticityRisk: p.profile.spasticityRisk,
      })
      .run();

    const exerciseIds =
      p.severity === "severe"
        ? ["elbow_flex", "wrist_ext", "knee_flex"]
        : ["elbow_flex", "shoulder_abd", "wrist_ext", "knee_flex"];

    db.insert(schema.protocols)
      .values({
        patientId: p.id,
        exercises: JSON.stringify(exerciseIds),
        targetRepsPerDay: p.targetRepsPerDay,
        maxAssistPct: p.id === "p-peretz" ? 80 : 95,
        sessionMinutes: 30,
        updatedAt: now.toISOString(),
      })
      .run();

    // History: full days 0 .. acuteDay-2, partial today (only morning sessions).
    for (let dayIndex = 0; dayIndex < p.acuteDay; dayIndex++) {
      const isToday = dayIndex === p.acuteDay - 1;
      const dayRng = mulberry32(hashSeed("day", p.id, dayIndex));
      const sessionsToday = isToday
        ? Math.min(2, SESSION_HOURS.length) // morning sessions only for "today"
        : 3 + Math.floor(dayRng() * 3);

      // Severe patients ramp up slowly over the first days.
      const rampFactor = Math.min(1, 0.4 + 0.2 * dayIndex);
      const dayTarget = Math.round(p.targetRepsPerDay * p.adherence * rampFactor);
      if (dayTarget === 0) continue;
      const perSession = Math.max(20, Math.round(dayTarget / sessionsToday));

      for (let s = 0; s < sessionsToday; s++) {
        const exerciseId = exerciseIds[(dayIndex + s) % exerciseIds.length];
        const sessionSeed = seedForSession(p.id, dayIndex, s);
        const targetReps = Math.max(
          10,
          Math.round(perSession * (0.85 + dayRng() * 0.3))
        );
        const sim = simulateSession({
          profile: p.profile,
          dayIndex,
          seed: sessionSeed,
          maxAssistPct: p.id === "p-peretz" ? 80 : 95,
          targetReps,
        });

        const start = new Date(admission);
        start.setDate(start.getDate() + dayIndex);
        start.setHours(Math.floor(SESSION_HOURS[s]), (SESSION_HOURS[s] % 1) * 60, 0, 0);
        const end = new Date(start.getTime() + sim.durationMs);
        const sessionId = `s-${p.id}-${dayIndex}-${s}`;

        db.insert(schema.sessions)
          .values({
            id: sessionId,
            patientId: p.id,
            exerciseId,
            startedAt: start.toISOString(),
            endedAt: end.toISOString(),
            repCount: sim.repCount,
            avgPatientRangePct: sim.avgPatientRangePct,
            avgAssistPct: sim.avgAssistPct,
            avgQuality: sim.avgQuality,
            avgRomPct: sim.avgRomPct,
            operator: s >= 3 ? "family" : "patient",
          })
          .run();

        // Insert reps in chunks to keep statements bounded.
        const repRows = sim.reps.map((r) => ({
          sessionId,
          tMs: r.tMs,
          initiationVelDegS: r.initiationVelDegS,
          patientRangePct: r.patientRangePct,
          assistPct: r.assistPct,
          quality: r.quality,
          romPct: r.romPct,
          durationMs: r.durationMs,
        }));
        for (let i = 0; i < repRows.length; i += 200) {
          db.insert(schema.reps).values(repRows.slice(i, i + 200)).run();
        }

        for (const ev of sim.safetyEvents) {
          db.insert(schema.safetyEvents)
            .values({
              sessionId,
              patientId: p.id,
              type: ev.type,
              atIso: new Date(start.getTime() + ev.atMs).toISOString(),
              // Past days' events reviewed; today's still open.
              acknowledged: isToday ? 0 : 1,
            })
            .run();
        }
      }
    }
  }
}

// CLI entry: `npm run seed`
if (process.argv[1]?.endsWith("seed.ts")) {
  (async () => {
    const { db } = await import("./index");
    seed(db);
    const count = db.select().from(schema.sessions).all().length;
    console.log(`Seeded ${PATIENTS.length} patients, ${count} sessions.`);
  })();
}

export { EXERCISES };
